class Solution:
    def hasLowHighBetween(self, values: List[int]) -> bool:
        n = len(values)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if values[i] < values[k] < values[j]:
                        return True
        return False

