class Solution:
    def hasLowHighBetween(self, values: List[int]) -> bool:
        mid = float("-inf")
        stack = []
        for v in reversed(values):
            if v < mid:
                return True
            while stack and stack[-1] < v:
                mid = stack.pop()
            stack.append(v)
        return False

