class Solution {
    public boolean hasLowHighBetween(int[] values) {
        long mid = Long.MIN_VALUE;
        int[] stack = new int[values.length];
        int top = 0;
        for (int i = values.length - 1; i >= 0; i--) {
            if (values[i] < mid) return true;
            while (top > 0 && stack[top - 1] < values[i]) mid = stack[--top];
            stack[top++] = values[i];
        }
        return false;
    }
}

