class Solution {
public:
    bool hasLowHighBetween(vector<int>& values) {
        long long mid = LLONG_MIN;
        vector<int> stack;
        for (int i = (int) values.size() - 1; i >= 0; i--) {
            if (values[i] < mid) return true;
            while (!stack.empty() && stack.back() < values[i]) {
                mid = stack.back();
                stack.pop_back();
            }
            stack.push_back(values[i]);
        }
        return false;
    }
};

