bool hasLowHighBetween(int* values, int valuesSize) {
    long long mid = LLONG_MIN;
    int* stack = malloc(valuesSize * sizeof(int));
    int top = 0;
    bool found = false;
    for (int i = valuesSize - 1; i >= 0 && !found; i--) {
        if (values[i] < mid) { found = true; break; }
        while (top > 0 && stack[top - 1] < values[i]) mid = stack[--top];
        stack[top++] = values[i];
    }
    free(stack);
    return found;
}
